import {importWorkspaceDocument} from './document-import.mjs';
import {withStableView} from './view-stability.mjs';
import {mountLiteratureAi} from './literature-ai.mjs';
import {literatureParagraphs} from './literature-ai-model.mjs';
import {toolBanner} from './tool-banner.mjs';
import {openWritingReferenceSearch,newReferenceSearchItems} from './writing-reference-search.mjs';
import {registerEditor,markEditorSaved,editorHasWork,clearEditor} from './edit-guard.mjs';
import {literatureKey,readingStates,scopes,validatePaper,selectLiterature,mergeLiteratureBackup,markOpened} from './literature-model.mjs';
import {list,write,projects} from './state.mjs';
import {esc,icon,empty,formatDate,download} from './ui.mjs';
const $=s=>document.querySelector(s);
let filters={status:'all',project:'all',tag:'all',query:'',sort:'added'};
const papers=()=>list(literatureKey);
const projectName=id=>projects().find(p=>p.id===id)?.name||'未归入项目';
const readerUrl=p=>'#literature/'+encodeURIComponent(p.id);
const stateLabel=p=>readingStates.find(s=>s[0]===p.status)?.[1]||'待读';
const recommendationRows=(rows,query='')=>{const q=query.trim().toLocaleLowerCase();const tagCounts=rows.flatMap(p=>p.tags||[]).reduce((m,t)=>m.set(t,(m.get(t)||0)+1),new Map());return rows.map(p=>{const tags=p.tags||[];const hay=[p.title,p.authors,p.doi,...tags].join(' ').toLocaleLowerCase();const queryHit=q?(hay.includes(q)?12:0):0;const tagScore=tags.reduce((n,t)=>n+(tagCounts.get(t)||0),0);const noteScore=(p.notes?.length||0)*.5;const recent=Date.parse(p.lastReadAt||p.createdAt)||0;return {paper:p,score:queryHit+tagScore+noteScore+recent/1e13};}).filter(x=>!q||x.score>0).sort((a,b)=>b.score-a.score).slice(0,6).map(x=>x.paper);};
const recommendationRowsMarkup=(rows,query='')=>{const recs=recommendationRows(rows,query);return recs.map(p=>`<a class="lit-recommend-row" href="${readerUrl(p)}"><span class="hub-row-icon">${icon('book',17)}</span><span><b>${esc(p.title)}</b><small>${esc(p.authors||'作者未填写')} · ${esc(p.year||'年份未填写')}</small><em>${(p.tags||[]).slice(0,3).map(t=>esc(t)).join(' · ')||'已保存文献'}</em></span>${icon('arrow',14)}</a>`).join('')||`<div class="lit-recommend-empty">${rows.length?'没有匹配的本地文献，请换一个主题或关键词。':'还没有可用于推荐的本地文献。先导入或添加一篇文献，再根据标题和标签生成相关推荐。'}</div>`;};
function persist(p,notify){try{const rows=papers(),i=rows.findIndex(r=>r.id===p.id);if(i<0){if(rows.length>=200){notify('文献库最多保存 200 篇，请先导出备份。');return false;}rows.unshift(p);}else rows[i]=p;write(literatureKey,rows);return true;}catch{notify('保存失败，请先导出备份并检查浏览器空间。');return false;}}
const heading=(title,description,actions='',extraClass='')=>toolBanner('literature',{title,description,actions,extraClass});
const noteRows=(rows)=>rows.flatMap(p=>p.notes.map(n=>({...n,paper:p}))).sort((a,b)=>(Date.parse(b.updatedAt)||0)-(Date.parse(a.updatedAt)||0));
function row(p){return `<tr><td><div class="lit-name"><span class="hub-row-icon">${icon('file',19)}</span><div><a href="${readerUrl(p)}">${esc(p.title)}</a><small>${esc(p.authors||'作者未填写')} · ${esc(p.year||'年份未填写')}</small><div class="lit-tags"><span>${esc(projectName(p.projectId))}</span>${p.tags.slice(0,2).map(t=>`<span>${esc(t)}</span>`).join('')}</div></div></div></td><td><span class="lit-scope ${p.scope}">${scopes[p.scope]||'仅元数据'}</span></td><td><span class="lit-state ${p.status}"><i></i>${stateLabel(p)}</span></td><td><div class="lit-actions"><a href="${readerUrl(p)}">${p.scope==='metadata'?'查看信息':p.status==='reading'?'继续阅读':p.scope==='abstract'?'查看摘要':'开始阅读'}</a><button data-lit-edit="${esc(p.id)}" aria-label="编辑文献信息：${esc(p.title)}">⋯</button></div></td></tr>`;}
function sourceInfo(paper){const providers={crossref:'Crossref',europepmc:'Europe PMC',openalex:'OpenAlex'},online=Object.hasOwn(providers,paper.source),provider=providers[paper.source],label=online?(paper.sourceLabel||provider+' · 在线题录，未读取全文'):'';return `<details class="lit-source-info" ${paper.scope==='metadata'?'open':''}><summary>来源与文件信息 <span>${online?(paper.scope==='metadata'?'在线题录 · 全文未读取':'在线题录 · 正文由你补充'):'未联网核验'}</span></summary>${online?`<p>题录来源：${esc(label)}</p>`:''}<p>DOI：${paper.doi?`<a href="https://doi.org/${encodeURI(paper.doi)}" target="_blank" rel="noopener noreferrer">${esc(paper.doi)}</a>`:'未提供'}<br>URL：${paper.url?`<a href="${esc(paper.url)}" target="_blank" rel="noopener noreferrer">${esc(paper.url)}</a>`:'未提供'}<br>文件：${esc(paper.fileName||(online?'未导入本地文件':'手动录入'))}</p>${online?'<p>在线检索保存的是题录信息，不代表已获取、读取或核验全文。正文和摘要需由你另行导入并核对来源。</p>':''}</details>`;}
function sidebars(rows){const recent=rows.filter(p=>p.lastReadAt).sort((a,b)=>Date.parse(b.lastReadAt)-Date.parse(a.lastReadAt)).slice(0,3),notes=noteRows(rows).slice(0,3);return `<section class="card lit-side-card"><h2>最近阅读</h2>${recent.map(p=>`<a class="lit-side-row" href="${readerUrl(p)}">${icon('book',18)}<span><b>${esc(p.title)}</b><small>最近打开 · ${formatDate(p.lastReadAt)}</small></span>${icon('arrow',13)}</a>`).join('')||'<p class="lit-side-empty">打开文献后，在这里继续阅读。不会自动标记已读。</p>'}</section><section class="card lit-side-card"><h2>最近笔记</h2>${notes.map(n=>`<a class="lit-side-row" href="${readerUrl(n.paper)}?tab=notes">${icon('pen',18)}<span><b>${esc(n.text.slice(0,70))}</b><small>${esc(n.paper.title)} · ${formatDate(n.updatedAt)}</small></span></a>`).join('')||'<p class="lit-side-empty">阅读时保存自己的思考，笔记会关联到文献。</p>'}</section><section class="card lit-side-card lit-scope-help"><h2>来源与材料范围</h2><p><b>已有正文</b>：查看已导入的文本</p><p><b>仅摘要</b>：只基于摘要阅读</p><p><b>仅元数据</b>：标题、作者等信息</p><small>正文来自用户输入或本地解析，不保证原文完整；在线题录会标明检索来源，不代表已读取全文。</small></section>`;}
export function mountLiterature(ctx){clearEditor();return withStableView($('.dashboard'),()=>mountLiteratureContents(ctx));}function mountLiteratureContents({modal,notify}){const rows=papers(),tags=[...new Set(rows.flatMap(p=>p.tags))],noteCount=rows.reduce((sum,p)=>sum+(p.notes?.length||0),0);$('.dashboard').innerHTML=`<div class="lit-workspace-refresh rdc-reading-space rdc-library-space">${heading('AI 研读','管理文献、检索资料、研读正文，并整理翻译内容。',`<button class="btn primary" data-lit-import>${icon('upload',16)} 导入文献</button><button class="btn secondary" data-lit-add>${icon('plus',16)} 手动添加</button>`)}<div class="lit-overview-strip"><div><span class="lit-overview-kicker">YOUR READING SPACE</span><h2>把文献变成你的研究积累</h2><p>从导入资料到阅读笔记，四种方式连接你的研究。</p></div><dl><div><dt>文献</dt><dd>${rows.length}<small>篇</small></dd></div><div><dt>阅读中</dt><dd>${rows.filter(p=>p.status==='reading').length}<small>篇</small></dd></div><div><dt>笔记</dt><dd>${noteCount}<small>条</small></dd></div></dl></div><section class="lit-feature-grid" aria-label="AI 研读功能">${[
 ['blue','book','我的文献','统一管理正文、摘要与来源','本地文献库','data-lit-tool="0"'],
 ['orange','search','文献检索','查找在线题录与已保存的文献','在线与本地','data-lit-entry="search"'],
 ['mint','file','文献研读','基于实际原文解读、问答与笔记','原文可定位','data-lit-tool="1"'],
 ['violet','language','文献翻译','按段生成译文，保留原文与术语','AI 对照翻译','data-lit-tool="3"']
].map(([color,glyph,title,description,state,action],index)=>`<button class="lit-feature-card ${color}" ${action}><span class="lit-feature-art" aria-hidden="true">${icon(glyph,52)}</span><span class="lit-feature-top"><span class="lit-feature-icon">${icon(glyph,22)}</span><span class="lit-feature-state">${state}</span></span><span class="lit-feature-copy"><b>${title}</b><small>${description}</small></span><span class="lit-feature-bottom"><span>0${index+1} / ${index===0?'管理':index===1?'查找':index===2?'阅读':'整理'}</span>${icon('arrow',16)}</span></button>`).join('')}</section><div class="lit-service-scope">${icon('shield',16)}<span>支持在线题录检索、原文研读与对照翻译；AI 任务先确认费用，保存的本地文献请及时备份。</span><a href="#settings/data">数据与备份 →</a></div><div class="lit-layout"><section class="card lit-library rdc-library-panel" id="lit-library"><header><div class="rdc-heading-copy"><span class="rdc-section-kicker">LIBRARY · 我的资料</span><h2>我的文献库 <small>${rows.length} 篇</small></h2><p>把原文、来源和阅读记录放在一起。</p></div><div class="hub-tabs lit-tabs" data-scroll-key="lit-tabs-1" role="group" aria-label="阅读状态">${readingStates.map(([id,name])=>`<button data-lit-status="${id}" class="${filters.status===id?'active':''}" aria-pressed="${filters.status===id}">${name} <span>${id==='all'?rows.length:rows.filter(p=>p.status===id).length}</span></button>`).join('')}</div></header><div class="lit-toolbar"><label class="asset-search">${icon('search',16)}<input id="lit-query" aria-label="搜索文献" value="${esc(filters.query)}" placeholder="搜索标题、作者或 DOI"></label><select id="lit-project" aria-label="文献项目"><option value="all">所有项目</option><option value="none" ${filters.project==='none'?'selected':''}>未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${filters.project===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="lit-tag" aria-label="文献标签"><option value="all">全部标签</option>${tags.map(t=>`<option value="${esc(t)}" ${filters.tag===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="lit-sort" aria-label="文献排序">${[['added','最近添加'],['read','最近打开'],['title','标题排序']].map(([v,n])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="lit-table-scroll" data-scroll-key="lit-table-scroll-1" role="region" aria-label="文献列表，可横向滚动" tabindex="0"><table class="lit-table"><thead><tr><th scope="col">文献信息</th><th scope="col">材料范围</th><th scope="col">阅读状态</th><th scope="col">操作</th></tr></thead><tbody id="lit-rows"></tbody></table></div><footer><span id="lit-count"></span> · 阅读状态由你标记</footer></section></div><div class="asset-backup">${icon('shield',22)}<div><b>本地文献，请及时备份</b><p>保存的正文、元数据与笔记可导出为文献备份。</p></div><button class="btn secondary" data-lit-backup>导出文献备份</button></div></div>`;
const update=()=>withStableView($('.dashboard'),()=>{const chosen=selectLiterature(rows,filters,projects());$('#lit-count').textContent=`共 ${chosen.length} 篇文献`;$('#lit-rows').innerHTML=chosen.map(row).join('')||`<tr><td colspan="4"><div class="asset-empty rdc-library-empty">${icon('book',32)}<h3>${rows.length?'没有匹配的文献':'添加第一篇文献，开始整理研究资料'}</h3><p>${rows.length?'尝试调整关键词、项目或标签。':'导入正文，或手动记录标题、作者与来源。'}</p><button class="btn ${rows.length?'secondary':'primary'}" ${rows.length?'data-lit-reset':'data-lit-add'}>${rows.length?'清除筛选':'添加文献'}</button></div></td></tr>`;document.querySelectorAll('[data-lit-status]').forEach(b=>{b.classList.toggle('active',b.dataset.litStatus===filters.status);b.setAttribute('aria-pressed',b.dataset.litStatus===filters.status);});});update();$('#lit-query').addEventListener('input',e=>{filters.query=e.target.value;update();});for(const [id,key] of [['lit-project','project'],['lit-tag','tag'],['lit-sort','sort']])$('#'+id).addEventListener('change',e=>{filters[key]=e.target.value;update();});$('.dashboard').addEventListener('click',e=>{const status=e.target.closest('[data-lit-status]');if(status){filters.status=status.dataset.litStatus;update();}if(e.target.closest('[data-lit-reset]')){filters={status:'all',project:'all',tag:'all',query:'',sort:'added'};mountLiterature({modal,notify});}} ,{signal:pageSignal()});bindActions({modal,notify});}
let pageController;
function pageSignal(){pageController?.abort();pageController=new AbortController();return pageController.signal;}
function recommendLiterature({modal}){const rows=papers();modal('推荐文献',`<p class="hub-description">基于你已保存文献的标题、标签、阅读记录和笔记，生成本地相关推荐。结果来自当前浏览器，不代表在线数据库检索或真实推荐。</p><form id="lit-recommend-form" class="lit-recommend-form"><label for="lit-recommend-query">研究主题或关键词（可选）</label><div><input id="lit-recommend-query" maxlength="120" placeholder="例如：课堂反馈、机器学习、乡村振兴"><button class="btn primary" type="submit">生成推荐</button></div></form><div id="lit-recommend-results" class="lit-recommend-results">${recommendationRowsMarkup(rows)}</div><p class="hub-footnote">想获得更多候选？请先导入文献，或在文献库中补充标题与标签。</p>`);const form=$('#lit-recommend-form'),results=$('#lit-recommend-results');form.addEventListener('submit',e=>{e.preventDefault();results.innerHTML=recommendationRowsMarkup(rows,$('#lit-recommend-query').value);});}
export function openLiteratureSearch({modal,notify=()=>{}}){
 return openWritingReferenceSearch({modal,mode:'search',destination:'文献库',getExisting:papers,
  onLocalSearch:()=>openLocalLiteratureSearch({modal,notify}),
  onImport:(items,{isCurrent})=>{
   if(!isCurrent())throw Error('检索页面已关闭，请重新打开后添加。');
   const existing=papers(),fresh=newReferenceSearchItems(items,existing),now=new Date().toISOString();
   if(existing.length+fresh.length>200)throw Error('文献库最多保存 200 篇，请先导出备份并整理文献。');
   const added=fresh.map(item=>validatePaper({...item,scope:'metadata',text:'',status:'unread',projectId:'',notes:[],warnings:[],createdAt:now,updatedAt:now}));
   try{write(literatureKey,[...added,...existing]);}catch{throw Error('文献库保存失败，所选题录仍保留。请检查浏览器空间后重试。');}
   if(document.querySelector('.dashboard #lit-library')&&!editorHasWork())mountLiterature({modal,notify});
   notify(`已保存 ${added.length} 篇在线题录；全文尚未读取。`);
  }});
}
function openLocalLiteratureSearch({modal,notify}){const rows=papers();modal('文献检索',`<div class="rdc-dialog rdc-search-dialog"><div class="lit-modal-intro"><span>${icon('search',22)}</span><div><b>从你的文献库找到依据</b><p>输入标题、作者、DOI 或标签，在已保存资料中查找。</p></div></div><div class="wrs-local-navigation"><span>当前浏览器的文献库</span><button type="button" class="btn secondary" data-lit-online-search>检索在线数据库 →</button></div><form id="lit-search-form" class="lit-search-form" data-unprotected><label for="lit-search-query">关键词</label><div><input id="lit-search-query" maxlength="200" placeholder="搜索标题、作者、DOI 或标签"><button class="btn primary" type="submit">搜索本地库</button></div></form><div class="rdc-dialog-section-head"><b>本地检索结果</b><span>当前浏览器的文献库</span></div><div id="lit-search-results" class="lit-search-results">${rows.slice(0,5).map(p=>`<a href="${readerUrl(p)}"><span><b>${esc(p.title)}</b><small>${esc(p.authors||'作者未填写')} · ${esc(p.year||'年份未填写')}</small></span>${icon('arrow',14)}</a>`).join('')||'<p class="lit-recommend-empty">暂无本地文献。先导入或添加文献，再进行搜索。</p>'}</div></div>`);const form=$('#lit-search-form'),results=$('#lit-search-results');form.addEventListener('submit',e=>{e.preventDefault();const query=$('#lit-search-query').value.trim();const found=selectLiterature(rows,{query},projects());results.innerHTML=found.map(p=>`<a href="${readerUrl(p)}"><span><b>${esc(p.title)}</b><small>${esc(p.authors||'作者未填写')} · ${esc(p.year||'年份未填写')}</small></span>${icon('arrow',14)}</a>`).join('')||'<p class="lit-recommend-empty">没有匹配的本地文献，请换一个关键词或先导入材料。</p>';});$('#workspace-dialog [data-lit-online-search]')?.addEventListener('click',()=>openLiteratureSearch({modal,notify}));}
function bindActions({modal,notify}){const root=$('.dashboard');root.addEventListener('click',async e=>{if(e.target.closest('[data-lit-add]'))paperForm(null,{modal,notify});if(e.target.closest('[data-lit-import]'))paperForm(null,{modal,notify},true);const entry=e.target.closest('[data-lit-entry]');if(entry){if(entry.dataset.litEntry==='recommend')recommendLiterature({modal});if(entry.dataset.litEntry==='import')paperForm(null,{modal,notify},true);if(entry.dataset.litEntry==='search')openLiteratureSearch({modal,notify});return;}const edit=e.target.closest('[data-lit-edit]');if(edit&&editorHasWork()){notify('请先保存当前笔记，再编辑文献信息。');return;}if(edit)paperForm(papers().find(p=>p.id===edit.dataset.litEdit),{modal,notify});if(e.target.closest('[data-lit-backup]')){try{await download('PaperKnow-文献备份.json',JSON.stringify({format:'paperknow-literature-backup',version:1,exportedAt:new Date().toISOString(),papers:papers()},null,2),'application/json');notify('已发起文献备份下载，请确认文件已保存。');}catch(error){notify(error.message);}}const tool=e.target.closest('[data-lit-tool]');if(tool){const type=Number(tool.dataset.litTool);if(type===0){document.querySelector('#lit-library')?.scrollIntoView?.({behavior:'smooth',block:'start'});return;}if(type===1){const p=papers().filter(p=>p.scope!=='metadata').sort((a,b)=>(Date.parse(b.lastReadAt)||0)-(Date.parse(a.lastReadAt)||0))[0];if(p)location.hash=readerUrl(p);else paperForm(null,{modal,notify},true);}else if(type===2)reviewComparison({modal,notify});else if(type===3)openLiteratureTranslation({modal,notify});}} ,{signal:pageController.signal});}
function paperForm(existing,{modal,notify},importMode=false){let text=existing?.text||'',fileName=existing?.fileName||'',warnings=existing?.warnings||[],busy=false;modal(existing?'编辑文献信息':importMode?'导入文献':'添加文献',`<form id="lit-form" class="hub-form rdc-paper-form"><div class="rdc-import-intro"><span>${icon('book',24)}</span><div><b>${existing?'完善这篇文献的信息':'把研究资料收进文献库'}</b><p>导入正文或手动记录来源，建立自己的阅读资料。</p></div></div><p class="hub-footnote">支持 DOCX / PDF / TXT；PaperKnow JSON 可恢复文献备份。</p><label for="lit-upload" class="lit-upload rdc-literature-upload"><span class="rdc-upload-symbol">${icon('upload',24)}</span><span><b>${importMode?'选择文档或文献备份':'导入正文（可选）'}</b><small>TXT / DOCX 最大 50MB · PDF 云解析 20MB / 100 页 · JSON 备份 10MB</small></span><input id="lit-upload" type="file" accept=".docx,.pdf,.txt,.json"></label><p id="lit-parse-status" role="status"></p><fieldset class="rdc-form-group"><legend>01 · 文献信息</legend><label for="lit-title">文献标题 *</label><input id="lit-title" required maxlength="300" value="${esc(existing?.title||'')}"><div class="hub-form-row"><div><label for="lit-authors">作者</label><input id="lit-authors" maxlength="1000" value="${esc(existing?.authors||'')}" placeholder="多位作者可用顿号分隔"></div><div><label for="lit-year">年份</label><input id="lit-year" pattern="[0-9]{4}" maxlength="4" value="${esc(existing?.year||'')}" placeholder="例如：2025"></div></div></fieldset><fieldset class="rdc-form-group"><legend>02 · 归类与来源</legend><label for="lit-association">所属项目</label><select id="lit-association"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===existing?.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label for="lit-tags-input">标签（用逗号分隔）</label><input id="lit-tags-input" maxlength="500" value="${esc(existing?.tags?.join('，')||'')}" placeholder="例如：课堂反馈，教育研究"><div class="hub-form-row"><div><label for="lit-doi">DOI（可选）</label><input id="lit-doi" maxlength="300" value="${esc(existing?.doi||'')}" placeholder="10.1234/example"></div><div><label for="lit-url">来源 URL（可选）</label><input id="lit-url" type="url" maxlength="2000" value="${esc(existing?.url||'')}" placeholder="https://…"></div></div></fieldset><fieldset class="rdc-form-group"><legend>03 · 阅读材料</legend><div class="hub-form-row"><div><label for="lit-scope-input">材料范围</label><select id="lit-scope-input">${Object.entries(scopes).map(([v,n])=>`<option value="${v}" ${v===(existing?.scope||'metadata')?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="lit-state-input">阅读状态</label><select id="lit-state-input">${readingStates.slice(1).map(([v,n])=>`<option value="${v}" ${v===(existing?.status||'unread')?'selected':''}>${n}</option>`).join('')}</select></div></div><label for="lit-text-input">正文 / 摘要（最多 200,000 字符）</label><textarea id="lit-text-input" rows="6" maxlength="200000" placeholder="粘贴有权使用的正文或摘要；仅元数据模式不保存此栏文本。">${esc(text)}</textarea></fieldset><p class="hub-footnote">TXT / DOCX 在本地提取文字；PDF（含扫描件）需登录并确认云端解析，原件与解析任务保留在账户。文献库保存的是文本副本，来源信息仍需核对。</p><p id="lit-error" class="hub-error" role="alert"></p><button class="btn primary" id="lit-submit" type="submit">${existing?'保存修改':'加入文献库'}</button>${existing?'<button class="btn secondary" type="button" id="lit-delete">移除此本地文献</button>':''}</form>`);const form=$('#lit-form');$('#lit-delete')?.addEventListener('click',()=>{if(!window.confirm('仅删除当前浏览器中的此文献、笔记、研读与翻译结果，不删除账户原件或任务。请先导出文献备份。确认删除？'))return;try{write(literatureKey,papers().filter(p=>p.id!==existing.id));$('#workspace-dialog').close();mountLiterature({modal,notify});notify('本地文献已移除；账户文件与任务保留。');}catch{notify('移除失败，文献仍保留，请检查浏览器存储。');}});$('#lit-upload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file||busy)return;if(file.size>50*1024*1024){$('#lit-error').textContent='文件不可超过 50MB。';return;}busy=true;$('#lit-submit').disabled=true;$('#lit-parse-status').textContent='正在本地读取…';try{if(/\.json$/i.test(file.name)){if(file.size>10*1024*1024)throw Error('文献备份不可超过 10MB。');const backup=JSON.parse(await file.text());if($('#lit-form')!==form)return;const result=mergeLiteratureBackup(papers(),backup);write(literatureKey,result.papers);$('#workspace-dialog').close();mountLiterature({modal,notify});notify(`恢复 ${result.added} 篇；${result.skipped} 篇已有记录保留原内容。`);return;}const parsed=await importWorkspaceDocument(file,$('#lit-parse-status'));if($('#lit-form')!==form)return;if(!parsed.text.trim())throw Error('未提取到正文，请核对解析提示或转换文档格式。');if(parsed.text.length>200000)throw Error('正文超过 200,000 字符，请按章节导入。');text=parsed.text;fileName=file.name;warnings=parsed.warnings||[];$('#lit-text-input').value=text;$('#lit-scope-input').value='full';if(!$('#lit-title').value)$('#lit-title').value=file.name.replace(/\.[^.]+$/,'');$('#lit-parse-status').textContent=`${fileName} · 已提取 ${text.length.toLocaleString('zh-CN')} 字符${warnings.length?' · '+warnings.slice(0,2).join('；'):''}`;$('#lit-error').textContent='';}catch(err){if($('#lit-form')===form)$('#lit-error').textContent=err.message||'导入失败，请检查文件。';}finally{busy=false;if($('#lit-form')===form){$('#lit-submit').disabled=false;$('#lit-upload').value='';}}});form.addEventListener('submit',e=>{e.preventDefault();if(busy)return;try{const now=new Date().toISOString();const p=validatePaper({...existing,id:existing?.id||crypto.randomUUID(),createdAt:existing?.createdAt||now,updatedAt:now,title:$('#lit-title').value,authors:$('#lit-authors').value,year:$('#lit-year').value,doi:$('#lit-doi').value,url:$('#lit-url').value,tags:$('#lit-tags-input').value,projectId:$('#lit-association').value,scope:$('#lit-scope-input').value,status:$('#lit-state-input').value,text:$('#lit-text-input').value,fileName,warnings,notes:existing?.notes||[]});if(existing?.text&&p.scope==='metadata'&&!window.confirm('切换为仅元数据会移除已保存的正文，笔记保留。确认继续？'))return;if(persist(p,notify)){$('#workspace-dialog').close();mountLiterature({modal,notify});notify('文献已保存到当前浏览器。');}}catch(err){$('#lit-error').textContent=err.message;}});}
export function mountLiteratureReader(id,{modal,notify},tab='text'){try{id=decodeURIComponent(id);}catch{}let paper=papers().find(p=>p.id===id);if(!paper){$('.dashboard').innerHTML=heading('文献不存在','当前浏览器没有这条文献记录。')+empty('返回文献库查看。','#category/literature');return;}if(paper.scope!=='metadata'){const opened=markOpened(paper);if(persist(opened,notify))paper=opened;}
$('.dashboard').innerHTML=`<div class="rdc-reading-space rdc-reader-space">${heading(paper.title,`${paper.authors||'作者未填写'} · ${paper.year||'年份未填写'} · ${projectName(paper.projectId)}`,`<a class="btn secondary" href="#category/literature">返回文献库</a><button class="btn secondary" data-lit-edit="${esc(paper.id)}">编辑信息</button>`,'detail-service-banner')}<div class="lit-reader-meta lit-reader-meta-refresh"><span class="lit-scope ${paper.scope}">${scopes[paper.scope]}</span><label for="reader-state">阅读状态</label><select id="reader-state">${readingStates.slice(1).map(([v,n])=>`<option value="${v}" ${v===paper.status?'selected':''}>${n}</option>`).join('')}</select><span>状态由你标记 · 不自动判断已读</span></div><div class="lit-reading-layout"><section class="card lit-reading-main"><div class="rdc-document-heading"><span class="rdc-document-mark">${icon('book',21)}</span><div><span class="rdc-section-kicker">READING DESK</span><h2>${paper.scope==='abstract'?'摘要阅读':paper.scope==='metadata'?'文献来源':'原文研读'}</h2></div><span class="rdc-document-state">${paper.scope==='metadata'?'元数据记录':paper.text.length.toLocaleString('zh-CN')+' 字符'}</span></div><div class="hub-tabs" aria-label="阅读视图"><button data-read-tab="text" class="${tab!=='notes'?'active':''}">${paper.scope==='abstract'?'摘要':paper.scope==='metadata'?'来源信息':'导入正文'}</button><button data-read-tab="notes" class="${tab==='notes'?'active':''}">我的笔记 ${paper.notes.length}</button></div><section id="reader-text-pane" ${tab==='notes'?'hidden':''}>${sourceInfo(paper)}${paper.warnings.length?`<p class="lit-read-notice">解析提醒：${esc(paper.warnings.join('；'))}</p>`:''}<p class="lit-read-notice">${paper.scope==='metadata'?'当前仅有元数据，没有正文可供研读。':paper.scope==='abstract'?'当前仅阅读用户提供的摘要，不代表已获取全文。':'以下为用户输入或文件提取的正文，可能缺少图表、公式和页码。'}</p><article class="lit-read-text">${paper.text?literatureParagraphs(paper.text).map(p=>`<p id="lit-source-${p.id}"><small class="lit-ai-paragraph-label">第 ${p.index} 段</small>${esc(p.text)}</p>`).join(''):'可通过编辑信息补充正文或摘要。'}</article></section><section id="reader-notes-pane" ${tab!=='notes'?'hidden':''}><h2>我的笔记</h2><div id="reader-notes"></div></section></section><aside class="card lit-note-editor"><div class="rdc-note-heading"><span>${icon('pen',22)}</span><div><span class="lit-note-kicker">YOUR RESEARCH NOTES</span><h2>记录研究笔记</h2></div></div><p>保存自己的理解、问题或手动译文，关联到当前文献。</p><div class="rdc-note-prompts" aria-label="笔记整理方向"><span>研究问题</span><span>关键方法</span><span>待核对</span></div><form class="hub-form" id="lit-note-form"><label for="note-location">原文定位（可选）</label><input id="note-location" maxlength="300" placeholder="例如：研究方法段；请自行核对页码"><label for="note-text">笔记内容 *</label><textarea id="note-text" required maxlength="5000" rows="10" placeholder="记录结论、方法、局限或待核对的问题…"></textarea><button class="btn primary" type="submit">保存笔记</button><button class="btn secondary" type="button" id="note-cancel" hidden>取消编辑</button><p id="note-status" role="status"></p></form><div class="lit-note-boundary">${icon('pen',15)}<span>手动记录 · 当前浏览器保存</span></div><button class="btn secondary" id="note-export">导出笔记 TXT</button></aside></div></div>`;
const restored=paper.noteDraft&&typeof paper.noteDraft==='object'?paper.noteDraft:null;
let editingId=typeof restored?.editingId==='string'&&paper.notes.some(n=>n.id===restored.editingId)?restored.editingId:null;
if(restored){$('#note-text').value=String(restored.text||'').slice(0,5000);$('#note-location').value=String(restored.location||'').slice(0,300);$('#note-cancel').hidden=!editingId;$('#note-status').textContent='已恢复上次未提交的笔记草稿。';}
const noteValues=()=>({text:$('#note-text').value,location:$('#note-location').value,editingId});
const saveDraft=()=>{try{const rows=papers(),index=rows.findIndex(p=>p.id===id);if(index<0)throw Error('文献已不存在');const current=rows[index],v=noteValues(),updated={...current};if(v.text||v.location)updated.noteDraft={...v,updatedAt:new Date().toISOString()};else delete updated.noteDraft;rows[index]=updated;write(literatureKey,rows);paper=updated;markEditorSaved();$('#note-status').textContent=v.text||v.location?'笔记草稿已自动保存，点击“保存笔记”后加入笔记列表。':'';return true;}catch{$('#note-status').textContent='笔记草稿保存失败，当前编辑仍保留。';return false;}};
const renderNotes=()=>{$('#reader-notes').innerHTML=paper.notes.map(n=>`<section class="lit-note"><div><small>${esc(n.location||'未填写原文定位')} · ${formatDate(n.updatedAt)}</small><button data-edit-note="${esc(n.id)}">编辑</button></div><p>${esc(n.text)}</p></section>`).join('')||`<div class="rdc-note-empty">${icon('pen',30)}<h3>让阅读留下你的思考</h3><p>从一个问题、一处方法或一条待核对的结论开始。</p></div>`;};
renderNotes();const signal=pageSignal();$('.dashboard').addEventListener('click',e=>{const t=e.target.closest('[data-read-tab]');if(t)withStableView($('.dashboard'),()=>{const notes=t.dataset.readTab==='notes';$('#reader-text-pane').hidden=notes;$('#reader-notes-pane').hidden=!notes;document.querySelectorAll('[data-read-tab]').forEach(b=>b.classList.toggle('active',b===t));});const edit=e.target.closest('[data-edit-note]');if(edit){if(editingId===edit.dataset.editNote)return;if(editorHasWork()||$('#note-text').value||$('#note-location').value){notify('请先保存当前笔记，再编辑另一条笔记。');return;}const n=paper.notes.find(n=>n.id===edit.dataset.editNote);if(n){editingId=n.id;$('#note-text').value=n.text;$('#note-location').value=n.location;$('#note-cancel').hidden=false;$('#note-text').focus({preventScroll:true});markEditorSaved();}}},{signal});
bindActions({modal,notify});$('#reader-state').addEventListener('change',e=>{const previous=paper.status;const current=papers().find(p=>p.id===id);if(!current){e.target.value=previous;return;}const updated={...current,status:e.target.value,updatedAt:new Date().toISOString()};if(persist(updated,notify)){paper=updated;notify('阅读状态已更新。');}else e.target.value=previous;});
$('#lit-note-form').addEventListener('submit',e=>{e.preventDefault();const text=$('#note-text').value.trim();if(!text)return;const current=papers().find(p=>p.id===id);if(!current){$('#note-status').textContent='文献已不存在，当前编辑仍保留，请先复制备份。';return;}const now=new Date().toISOString(),old=current.notes.find(n=>n.id===editingId),n={id:old?.id||crypto.randomUUID(),text,location:$('#note-location').value.trim(),createdAt:old?.createdAt||now,updatedAt:now};if(!old&&current.notes.length>=100){notify('每篇文献最多 100 条笔记，请编辑已有笔记。');return;}const updated={...current,notes:old?current.notes.map(x=>x.id===n.id?n:x):[n,...current.notes],updatedAt:now};delete updated.noteDraft;if(persist(updated,notify)){paper=updated;editingId=null;$('#lit-note-form').reset();$('#note-cancel').hidden=true;markEditorSaved();$('#note-status').textContent='笔记已保存到当前浏览器。';renderNotes();document.querySelector('[data-read-tab="notes"]').textContent='我的笔记 '+paper.notes.length;}});
$('#note-cancel').addEventListener('click',()=>{try{const rows=papers(),index=rows.findIndex(p=>p.id===id);if(index<0)throw Error();const updated={...rows[index]};delete updated.noteDraft;rows[index]=updated;write(literatureKey,rows);paper=updated;editingId=null;$('#lit-note-form').reset();$('#note-cancel').hidden=true;$('#note-status').textContent='已取消本次编辑，已保存的笔记保留。';markEditorSaved();}catch{$('#note-status').textContent='暂时无法清除草稿，当前编辑仍保留。';}});
const aiContainer=document.createElement('div');aiContainer.className='lit-ai-workspace';$('.lit-reading-layout').before(aiContainer);const ai=mountLiteratureAi({container:aiContainer,ctx:{modal,notify},getPaper:()=>papers().find(p=>p.id===id),updatePaper:updater=>{const current=papers().find(p=>p.id===id);if(!current)throw Error('文献已不存在，请先导出当前结果。');const updated=updater(current);if(!persist(updated,notify))throw Error('结果保存失败，请检查浏览器空间后重试。');paper=updated;},initialOperation:tab==='translation'?'translate':'read'});signal.addEventListener('abort',()=>ai.dispose(),{once:true});
registerEditor({label:'文献笔记',ctx:{modal,notify},getValue:noteValues,save:saveDraft,saveDraft,dispose:()=>ai.dispose()});
$('#note-export').addEventListener('click',async()=>{try{if(!paper.notes.length){notify('还没有笔记，请先记录并保存。');return;}await download(paper.title+'-笔记.txt',[paper.title,...paper.notes.map(n=>`\n${n.location||'未填写定位'}\n${n.text}`)].join('\n'));notify('已发起笔记下载。');}catch(error){notify(error.message);}});}
function reviewComparison({modal,notify}){const rows=papers();modal('整理文献综述框架',`<p class="hub-description">选择文献，导出包含真实元数据与已有笔记的对照框架。研究方法和结论需自行核对填写，当前不会调用 AI。</p><form id="lit-compare-form" class="hub-form"><div class="lit-compare-list">${rows.map(p=>`<label><input type="checkbox" name="lit-compare" value="${esc(p.id)}"><span>${esc(p.title)}<small>${scopes[p.scope]} · ${esc(projectName(p.projectId))}</small></span></label>`).join('')||'<p>先添加文献，再整理综述。</p>'}</div><button class="btn primary" type="submit" ${rows.length?'':'disabled'}>导出对照框架 TXT</button><p id="compare-error" role="alert"></p></form>`);$('#lit-compare-form').addEventListener('submit',async e=>{try{e.preventDefault();const ids=[...document.querySelectorAll('input[name="lit-compare"]:checked')].map(n=>n.value),selected=rows.filter(p=>ids.includes(p.id));if(!selected.length){$('#compare-error').textContent='请至少选择一篇文献。';return;}const text=['PaperKnow 文献对照框架','仅整理用户提供的元数据与笔记；未分析正文、未调用 AI。',...selected.map(p=>`\n标题：${p.title}\n作者：${p.authors||'未提供'}\n年份：${p.year||'未提供'}\n材料范围：${scopes[p.scope]}\nDOI：${p.doi||'未提供'}\nURL：${p.url||'未提供'}\n研究问题：[待核对填写]\n研究方法：[待核对填写]\n主要发现：[待核对填写]\n局限：[待核对填写]\n已有笔记：${p.notes.map(n=>n.text).join('；')||'暂无'}`)].join('\n');await download('PaperKnow-文献对照框架.txt',text);notify('已发起对照框架下载。');}catch(error){const node=$('#compare-error');if(node)node.textContent=error.message;}});}

export function openLiteratureTranslation({modal,notify}){
 const rows=papers().filter(p=>p.scope!=='metadata'&&p.text?.trim());
 modal('文献翻译',`<div class="rdc-dialog rdc-translation-dialog"><div class="lit-modal-intro"><span>${icon('language',24)}</span><div><b>原文与译文，保持一一对应</b><p>选择有权使用的原文，确认语言与费用后生成对照译文。</p></div></div><ol class="rdc-mini-steps"><li><span>01</span>选择原文</li><li><span>02</span>确认语言与费用</li><li><span>03</span>核对、保存与导出</li></ol><div class="more-translation-picker">${rows.map(p=>`<a href="${readerUrl(p)}?tab=translation"><b>${esc(p.title)}</b><small>${esc(scopes[p.scope])} · 进入对照翻译 →</small></a>`).join('')||'<p class="hub-footnote">还没有可用原文。请导入有权使用的 DOCX / PDF / TXT，或手动添加原文。</p>'}</div><div class="rdc-dialog-actions"><button class="btn primary" id="translation-import">添加原文材料</button><span>研读与译文保存在对应文献中，可导出 TXT。</span></div></div>`);
 $('#translation-import').onclick=()=>paperForm(null,{modal,notify},true);
}
